def _coerce_parameter(spec: ParameterSpec, value: Any) -> Any:
    if spec.type == "int":
        if isinstance(value, bool) or not isinstance(value, int):
            if isinstance(value, float) and value.is_integer():
                value = int(value)
            else:
                raise CapabilityError(f"参数 {spec.name} 必须是整数，实际 {type(value).__name__}")
    elif spec.type == "float":
        if isinstance(value, bool) or not isinstance(value, int | float):
            raise CapabilityError(f"参数 {spec.name} 必须是数值，实际 {type(value).__name__}")
        value = float(value)
    elif spec.type == "str":
        if not isinstance(value, str):
            raise CapabilityError(f"参数 {spec.name} 必须是字符串")
        return value
    if spec.minimum is not None and value < spec.minimum:
        raise CapabilityError(f"参数 {spec.name}={value} 低于下限 {spec.minimum}")
    if spec.maximum is not None and value > spec.maximum:
        raise CapabilityError(f"参数 {spec.name}={value} 超过上限 {spec.maximum}")
    return value


